"""MIRROR-ONLY: runs inside a unit carrying the executor unit's exact [Service] sandbox (generated by the mirror script
from hermes-forget-executor.service, only ExecStart replaced). Prints one PROBE line: what the executor CAN and
CANNOT reach. Expected: Hermes conversation paths and its own state writable; Privacy DB readable but not writable;
cognitive/Core API data, provider key, broker/authority/witness, sudoers invisible; /etc and code read-only; no
network except 127.0.0.1."""

import os
import socket

ROOT_DATA = "/home/lilith/.hermes/lilith-os-dev/data"


def read(path):
    try:
        with open(path, "rb") as fh:
            data = fh.read(1)
        # InaccessiblePaths hides a file behind an empty mode-000 file, which root (CAP_DAC_OVERRIDE) can open:
        # only real content counts as READ.
        return "READ" if data else "HIDDEN"
    except FileNotFoundError:
        return "ABSENT"
    except PermissionError:
        return "DENIED"
    except OSError as exc:
        return "ERR" + str(exc.errno)


def write(path):
    try:
        with open(path, "ab") as fh:
            fh.write(b"")
        return "WRITE"
    except FileNotFoundError:
        return "ABSENT"
    except PermissionError:
        return "DENIED"
    except OSError as exc:
        return "EROFS" if exc.errno == 30 else "ERR" + str(exc.errno)


def connect(host, port):
    try:
        with socket.create_connection((host, port), timeout=2):
            return "OPEN"
    except OSError as exc:
        # EPERM/EACCES from IPAddressDeny, or a timeout when the packets are silently dropped: both blocked.
        return "BLOCKED" if exc.errno in (1, 13, None) else "ERR" + str(exc.errno)


results = {
    "privacy_read": read("/home/lilith/.hermes/lilith-os-dev/f9-drill/privacy_governance.f9drill.db"),
    "privacy_write": write("/home/lilith/.hermes/lilith-os-dev/f9-drill/privacy_governance.f9drill.db"),
    "cognitive_read": read("/home/lilith/.hermes/lilith-os-dev/f9-drill/cognitive_memory.f9drill.db"),
    "drill_secret_read": read("/home/lilith/.hermes/lilith-os-dev/f9-drill/privacy-authority.f9drill.key"),
    "probe_db_read": read(f"{ROOT_DATA}/privacy_governance.dev.db"),
    "coreapi_db_read": read(f"{ROOT_DATA}/lilith-dev.db"),
    "provider_key_read": read("/etc/hermes-gateway-dev/provider.env"),
    "broker_read": read("/var/lib/lilith-memory-broker/probe"),
    "authority_read": read("/etc/lilith-authority-dev/probe"),
    "sudoers_read": read("/etc/sudoers"),
    "etc_write": write("/etc/f9c4-probe"),
    "code_write": write("/opt/hermes-gateway-dev/current/bin/hermes_forget_executor.py"),
    "hermes_home_write": write("/home/lilith/.hermes-dev/logs/probe.log"),
    "state_write": write("/var/lib/hermes-forget/state/probe"),
    "net_external": connect("10.20.0.2", 80),
    "net_metadata": connect("169.254.169.254", 80),
}
print("PROBE " + " ".join(f"{k}={v}" for k, v in sorted(results.items())), flush=True)
for p in ("/home/lilith/.hermes-dev/logs/probe.log", "/var/lib/hermes-forget/state/probe"):
    try:
        os.unlink(p)
    except OSError:
        pass
